\begin{tikzpicture}\begin{axis}[width=6.5cm,height=6cm,axis lines=middle,axis line style={-{Stealth}},xmin=0,xmax=11,ymin=0,ymax=40,xtick={0,1,...,11},ytick={0,4,...,40},grid=both,clip=false,scaled ticks=false,ticklabel style={font=\small,/pgf/number format/fixed},xlabel={$x$},ylabel={$\$ (1000s)$}]
